    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'Why did reformers in the 1830s and 1840s argue that cities needed parks?','[{"letter":"A","text":"They wanted to preserve aristocratic hunting grounds."},{"letter":"B","text":"They believed fresh air and exercise were necessary for public health."},{"text":"They hoped to increase the value of surrounding property.","letter":"C"},{"letter":"D","text":"They aimed to provide space for large public celebrations."}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'What did Olmsted find admirable about Birkenhead Park?','[{"letter":"A","text":"Its use of expensive imported plants."},{"text":"Its profitability compared with private gardens.","letter":"B"},{"letter":"C","text":"That rich and poor could enjoy it equally."},{"letter":"D","text":"That it preserved the area''s natural swamps."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'According to the passage, promoters hoped parks would influence the working classes by','[{"letter":"A","text":"encouraging sobriety and self-improvement."},{"text":"providing them with paid employment.","letter":"B"},{"letter":"C","text":"teaching them scientific gardening skills."},{"text":"offering cheaper alternatives to taverns.","letter":"D"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'What point does the final paragraph make about the miasma theory?','[{"letter":"A","text":"It is still accepted by modern scientists."},{"text":"It prevented parks from being built for many years.","letter":"B"},{"text":"It was proved wrong, but the parks it inspired remained useful.","letter":"C"},{"letter":"D","text":"It explained why parks reduce urban heat."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-reading-2','Gri Reading 2',true,'IELTS Academic Reading — Living Light: The Chemistry and Purpose of Ocean Glow') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'reading',20) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,title,passage_html) VALUES (v_sec,1,'Living Light: The Chemistry and Purpose of Ocean Glow','<p>Far below the sunlit surface of the sea lies a vast, dark realm where sunlight never penetrates. Yet this seemingly black world is punctuated by countless flashes, glimmers and steady glows produced by living organisms. This ability to generate light through a chemical reaction is known as bioluminescence, and it is astonishingly widespread. Scientists estimate that the majority of animals living in the open ocean can produce their own light, making bioluminescence one of the most common forms of communication on the planet, even though most people never witness it.</p><p>The light itself is the product of a reaction between two key components. A light-emitting molecule called luciferin reacts with oxygen, and this process is controlled by an enzyme named luciferase. When the two combine in the presence of oxygen, energy is released almost entirely as light rather than heat. For this reason, biologists often describe the glow as "cold light": less than twenty per cent of the energy is lost as heat, whereas an ordinary incandescent bulb wastes most of its energy warming its surroundings. Some organisms manufacture luciferin themselves, while others acquire it through their diet or by hosting colonies of luminous bacteria in specialised organs.</p><p>The colours that result are not random. In the deep ocean, blue and green light travels furthest through seawater, and so the overwhelming majority of marine species emit light within this narrow range. Red and yellow wavelengths are absorbed quickly by water and would be useless over distance. A small number of predators, however, have broken this rule. Certain dragonfish produce red light that most of their prey cannot even perceive, effectively granting them a private searchlight with which to hunt unseen.</p><p>Why organisms invest energy in producing light is a question with many answers, because bioluminescence serves strikingly different purposes. One of the most elegant is a form of camouflage called counter-illumination. Animals such as the hatchetfish carry rows of light-producing organs, known as photophores, along their bellies. By matching the faint glow of daylight filtering down from above, these fish erase their own silhouette, so that a predator looking upward sees no telltale dark shape against the brighter water. The disguise depends on adjusting the emitted light to the changing brightness overhead.</p><p>Light is also a powerful weapon and a means of escape. When threatened, some squid and shrimp eject a glowing cloud into the water, dazzling and confusing an attacker while they dart away into darkness. Others use light to attract a meal. The anglerfish is famous for a luminous lure that dangles above its mouth; smaller creatures, drawn towards the glow, swim directly into the predator''s jaws. In each of these cases the light is a tool of survival rather than a mere ornament.</p><p>Perhaps the most surprising role of bioluminescence is communication, particularly in the search for a mate. In the perpetual darkness of the deep, finding a partner of the same species is a formidable challenge. Many organisms solve it by flashing distinctive patterns of light, rather like a coded signal that only members of their own kind recognise. The timing, rhythm and position of these flashes can carry precise information, allowing individuals to identify one another across the void.</p><p>Bioluminescence is not confined to the depths. Near the surface, tiny single-celled organisms called dinoflagellates light up when disturbed, producing the shimmering blue waves that occasionally astonish swimmers and sailors at night. This flash is thought to be defensive: the sudden burst may startle a would-be grazer, or it may act as a "burglar alarm", drawing the attention of a larger predator to whatever is attacking the dinoflagellate. Either way, the glow improves the organism''s chances of survival.</p><p>Studying these phenomena is difficult, since bringing deep-sea animals to the surface usually destroys the delicate chemistry that makes them glow. Researchers therefore rely increasingly on remotely operated vehicles fitted with sensitive cameras to observe light in its natural setting. Their findings have reached well beyond marine biology. The luciferase enzyme, for instance, has become an invaluable laboratory tool: by attaching it to particular genes, scientists can make cells glow whenever those genes are active, illuminating processes that would otherwise remain hidden. In this way, a trick perfected by ocean creatures over millions of years now helps to advance modern medicine, proving that the living light of the sea is far more than a beautiful curiosity.</p>') RETURNING id INTO v_part;
