    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'According to the passage, which substance is responsible for controlling the light-producing reaction?','[{"text":"Oxygen","letter":"A"},{"letter":"B","text":"Luciferin"},{"text":"Luciferase","letter":"C"},{"letter":"D","text":"Bacteria"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'Why do most marine organisms produce blue or green light?','[{"letter":"A","text":"These colours are the easiest to generate chemically"},{"letter":"B","text":"These colours travel furthest through seawater"},{"letter":"C","text":"These colours cannot be seen by predators"},{"letter":"D","text":"These colours require the least energy to produce"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'What is suggested about the flash produced by dinoflagellates?','[{"text":"It is used to attract a mate in the darkness","letter":"A"},{"letter":"B","text":"It helps them to hunt smaller organisms"},{"text":"It may serve as a defensive \"burglar alarm\"","letter":"C"},{"text":"It matches the daylight coming from above","letter":"D"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'How has the luciferase enzyme proved useful outside marine biology?','[{"letter":"A","text":"It makes cells glow when particular genes are active"},{"letter":"B","text":"It allows deep-sea animals to survive at the surface"},{"letter":"C","text":"It improves the sensitivity of underwater cameras"},{"text":"It enables organisms to change the colour of their light","letter":"D"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-reading-3','Gri Reading 3',true,'IELTS Academic Reading — Ink, Iron, and the Multiplication of Words') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'reading',20) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,title,passage_html) VALUES (v_sec,1,'Ink, Iron, and the Multiplication of Words','<p>Before the middle of the fifteenth century, nearly every book in Europe was copied by hand. This was slow, laborious work, and monastic scribes might spend months or even years reproducing a single volume. Books were consequently rare and expensive, the preserve of wealthy institutions, aristocrats, and the Church. The transformation of this ancient practice is usually credited to Johannes Gutenberg, a goldsmith from the German city of Mainz, who around 1450 assembled a system of printing that would reshape the intellectual landscape of the continent.</p><p>Gutenberg''s genius lay not in any single invention but in the combination of several elements into a practical whole. Printing from carved wooden blocks was already known in East Asia, and had been used in Europe to produce images and short texts. His decisive contribution was movable type: individual letters cast in metal that could be arranged to form a page, dismantled, and reused indefinitely. To make these letters durable and uniform, he devised an alloy of lead, tin, and antimony, together with a hand-held mould that allowed identical pieces to be produced in quantity. He also adapted an oil-based ink that would adhere to metal, and modified the screw press, a device long used for pressing grapes and olives, to transfer ink evenly onto paper.</p><p>The rise of printing also depended on the earlier arrival of paper in Europe. Manufactured from rags and far cheaper than the parchment made from animal skins on which manuscripts had long relied, paper provided an affordable surface on which the new presses could work. The most celebrated product of Gutenberg''s workshop was the Bible printed around 1455, often called the Gutenberg Bible. About 180 copies were produced, some on paper and a smaller number on more costly vellum. The quality of the printing was so high that many contemporaries could scarcely distinguish the pages from fine manuscript work. Yet Gutenberg himself gained little from his achievement. Burdened by debt, he lost control of his workshop to his financial backer, Johann Fust, following a lawsuit, and died in relative obscurity.</p><p>The technology, however, spread with remarkable speed. Within a few decades, presses had been established in the major cities of Italy, France, and beyond; by 1500, printers across Europe had produced an estimated twenty million volumes. These early printed books are known as incunabula, from a Latin word meaning "cradle," reflecting the idea that they belonged to the infancy of printing. The sheer volume of material now available drove down prices and placed texts within reach of a growing class of merchants, students, and professionals.</p><p>The consequences extended far beyond the book trade. The wider availability of affordable texts encouraged the spread of literacy, though this was a gradual process rather than a sudden leap. Printing also standardised texts: whereas hand-copied manuscripts inevitably accumulated errors as each scribe introduced fresh mistakes, printed editions ensured that thousands of readers could consult identical words and diagrams. This reliability proved especially valuable in science, where the accurate reproduction of tables, charts, and illustrations allowed scholars in different countries to compare observations with confidence.</p><p>Perhaps the most dramatic effect was religious and political. When Martin Luther published his objections to Church practices in 1517, his ideas were rapidly printed and distributed in the vernacular, the everyday languages people actually spoke, rather than in scholarly Latin. Pamphlets and broadsheets carried arguments to audiences that no manuscript culture could have reached, and the Protestant Reformation became, in part, a contest fought through the printed page. Rulers and religious authorities, alarmed by this loss of control over information, responded by introducing systems of censorship and lists of prohibited books.</p><p>Historians continue to debate the precise weight of the printing press among the many forces that shaped early modern Europe. Some caution against treating the machine as an isolated cause, noting that rising literacy, expanding trade, and the growth of universities were already under way. Nevertheless, few dispute that printing accelerated these trends and gave them a new reach. By multiplying words on an unprecedented scale, the press helped turn knowledge into something that could circulate across borders, resist suppression, and accumulate from one generation to the next, an inheritance on which later scientific and cultural revolutions would build.</p>') RETURNING id INTO v_part;
