    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,6,'To keep his metal letters durable and uniform, Gutenberg created an alloy of lead, tin, and ______.','"antimony"'::jsonb,'["antimony"]'::jsonb);
