    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,3,10,13,'mcq_single','Choose the correct letter, A, B, C or D.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'According to the passage, Gutenberg''s decisive achievement was best described as:','[{"text":"combining several existing elements into a practical system","letter":"A"},{"text":"inventing paper as a cheap surface for printing","letter":"B"},{"text":"discovering how to make oil-based ink for the first time","letter":"C"},{"letter":"D","text":"carving individual wooden blocks to reproduce religious images"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'What happened to Gutenberg after the printing of his Bible?','[{"letter":"A","text":"He was generously rewarded by the Church"},{"letter":"B","text":"He lost control of his workshop"},{"text":"He set up presses across Italy and France himself","letter":"C"},{"letter":"D","text":"He went on profiting from printing for many more years"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'By 1500, European printers had produced an estimated:','[{"letter":"A","text":"180 volumes"},{"text":"two hundred million volumes","letter":"B"},{"letter":"C","text":"twenty million volumes"},{"letter":"D","text":"half a million volumes"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'What point do some historians make about the printing press?','[{"text":"It was the single most important cause of the Protestant Reformation","letter":"A"},{"letter":"B","text":"It had almost no effect on the spread of ideas"},{"letter":"C","text":"It caused literacy across Europe to decline"},{"letter":"D","text":"It accelerated trends that were already developing"}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-reading-4','Gri Reading 4',true,'IELTS Academic Reading — Rebuilding the Rainforests of the Sea') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'reading',20) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,title,passage_html) VALUES (v_sec,1,'Rebuilding the Rainforests of the Sea','<p>Coral reefs cover less than one percent of the ocean floor, yet they shelter roughly a quarter of all marine species, earning them the nickname "rainforests of the sea." The living architecture of a reef is built by tiny animals called coral polyps, which secrete a hard skeleton of calcium carbonate. Inside their tissues live microscopic algae known as zooxanthellae. This partnership is mutually beneficial: the algae photosynthesise and pass sugars to the coral, while the coral supplies the algae with shelter and nutrients. The vivid colours for which reefs are famous come largely from these resident algae.</p><p>When ocean temperatures rise even slightly above the seasonal maximum, this relationship breaks down. Stressed corals expel their algae, revealing the white skeleton beneath in a phenomenon called bleaching. A bleached coral is not dead, but it is starving, because it has lost its main source of food. If cooler conditions return quickly, the algae may recolonise and the coral can recover. Prolonged heat, however, is often fatal. The mass bleaching events recorded on Australia''s Great Barrier Reef in 2016 and 2017 killed corals across hundreds of kilometres, and scientists link their increasing frequency to global warming.</p><p>Warming is not the only threat. As the oceans absorb carbon dioxide from the atmosphere, seawater becomes more acidic, which makes it harder for polyps to build their skeletons. Nutrient run-off from farmland fuels blooms of algae that smother young corals, and overfishing removes the herbivorous fish that would normally graze this competing algae away. Coastal construction stirs up sediment that clouds the water and blocks the sunlight the zooxanthellae need. Individually, each pressure is damaging; together they can push a reef past the point of natural recovery.</p><p>Faced with these losses, researchers have turned to active restoration. The best-known technique is coral gardening, which borrows methods from horticulture. Small fragments are broken from healthy donor colonies and attached to underwater frames, ropes or tables in a nursery. Because many corals reproduce by fragmentation in the wild, these pieces continue to grow, sometimes several times faster in the sheltered nursery than on the open reef. Once the fragments reach a suitable size, divers transplant them onto degraded reef, fixing them in place with marine cement or epoxy. A single donor colony can, in this way, generate thousands of new corals.</p><p>Other approaches aim to make restoration more resilient rather than simply larger. In a process sometimes called assisted evolution, scientists selectively breed corals that have survived heatwaves, hoping to pass on their tolerance to the next generation. Larvae can also be reared in tanks and released onto reefs in enormous numbers, a method known as larval seeding. Some teams deploy "reef stars" — steel frames coated in sand — to stabilise rubble fields so that transplanted fragments are not swept away by currents. Sound is being trialled too: loudspeakers playing the crackle of a healthy reef appear to attract fish and larvae to silent, damaged areas.</p><p>None of these methods is a complete solution. Restoration is expensive and labour-intensive, and even the most successful projects have so far covered only a minute fraction of the world''s reefs. Critics warn that gardening a few hectares can distract from the underlying problem: unless greenhouse-gas emissions fall, warming and acidification will continue to outpace any planting effort. Supporters counter that restoration buys time, preserves genetic diversity and keeps skills and communities engaged until the climate stabilises.</p><p>What is clear is that reefs matter far beyond their beauty. They protect coastlines from storms, support fisheries that feed hundreds of millions of people, and underpin tourism worth billions of dollars each year. Chemicals derived from reef organisms have already yielded medicines. For all these reasons, the effort to understand and rebuild coral reefs has become one of the defining conservation challenges of the century.</p>') RETURNING id INTO v_part;
