    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'The high levels of phosphates and nitrogen in the Botai soil were interpreted as evidence of','[{"letter":"A","text":"burial pits dug for dead horses."},{"letter":"B","text":"the penning of animals in enclosures."},{"text":"intensive cultivation of crops.","letter":"C"},{"text":"the deliberate burning of grassland.","letter":"D"}]'::jsonb,'"B"'::jsonb);
