    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'What does the passage say about the proportion of REM sleep across a lifetime?','[{"letter":"A","text":"It remains constant from infancy to adulthood."},{"text":"It is higher in newborns than in adults.","letter":"B"},{"text":"It increases steadily as people grow older.","letter":"C"},{"letter":"D","text":"It is greatest in the elderly."}]'::jsonb,'"B"'::jsonb);
