    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'According to the passage, what causes modern steel-reinforced concrete to break apart when exposed to seawater or road salt?','[{"text":"The volcanic ash reacts violently with the salt","letter":"A"},{"letter":"B","text":"The steel rusts and expands inside the concrete"},{"letter":"C","text":"The Portland cement slowly dissolves in the water"},{"letter":"D","text":"The concrete gradually becomes too flexible"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'How did Roman marine concrete respond to being exposed to seawater?','[{"letter":"A","text":"It gradually dissolved away"},{"text":"It became increasingly brittle over time","letter":"B"},{"text":"It stayed completely unchanged chemically","letter":"C"},{"text":"It grew stronger as new minerals formed within it","letter":"D"}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'Why is Portland cement so widely used in modern construction?','[{"text":"It hardens quickly and predictably","letter":"A"},{"text":"It is able to heal its own cracks","letter":"B"},{"letter":"C","text":"It releases very little carbon dioxide"},{"letter":"D","text":"It can be made without any heating"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'What environmental benefit could a longer-lasting, self-healing concrete offer?','[{"text":"It would remove existing carbon dioxide from the atmosphere","letter":"A"},{"letter":"B","text":"It would need replacing far less often, cutting waste and pollution"},{"letter":"C","text":"It would make steel reinforcement much stronger"},{"text":"It would eliminate the need for lime entirely","letter":"D"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_tests (slug,name,is_published,description) VALUES ('gri-reading-10','Gri Reading 10',true,'IELTS Academic Reading — The Language of the Dawn Chorus') RETURNING id INTO v_test;
    INSERT INTO ielts_sections (test_id,section,duration_minutes) VALUES (v_test,'reading',20) RETURNING id INTO v_sec;
    INSERT INTO ielts_parts (section_id,part_number,title,passage_html) VALUES (v_sec,1,'The Language of the Dawn Chorus','<p>Long before the sun clears the horizon, woodlands across the temperate world erupt into sound. This phenomenon, known as the dawn chorus, is one of the most conspicuous displays of animal communication on the planet, yet its familiarity has done little to diminish the questions it raises among biologists. Why do birds invest so heavily in song, often at considerable energetic cost and at the very moment when a hungry predator might most easily locate them? The answers lie in the twin pressures that shape so much of avian life: competition for territory and the search for a mate.</p><p>It is important, at the outset, to distinguish between calls and songs. Calls are typically short, simple sounds that convey immediate information, such as the presence of a hawk overhead or contact between members of a flock. Song, by contrast, is more elaborate and, in most species, is produced predominantly by males during the breeding season. The organ responsible for this remarkable acoustic range is the syrinx, a structure unique to birds and located where the windpipe divides into the lungs. Because the syrinx has two independent sound sources, some birds can effectively sing two notes at once, producing internal harmonies that no human voice could match.</p><p>Perhaps the most surprising discovery of the twentieth century was that song, in many species, is not wholly innate but must be learned. Young songbirds pass through a sensitive period early in life during which they memorise the songs of adults around them, usually their fathers or neighbouring males. Experiments in which nestlings were raised in acoustic isolation demonstrated the consequences of this deprivation vividly: such birds grew up to produce only a crude, abnormal version of their species'' song. Crucially, the birds must also hear themselves practising, refining their output through a process of trial and error until it matches the memorised template. This developmental pathway bears an intriguing resemblance to the way human infants acquire speech.</p><p>Because song is learned rather than fixed by genetics alone, regional variations inevitably arise. Populations of the same species living in different valleys or on opposite sides of a mountain range often sing recognisably different versions of their song, a pattern biologists call a dialect. A white-crowned sparrow, for instance, can be assigned to its home population by an experienced ear alone. Dialects are transmitted culturally, passed from one generation to the next much as accents are among people, and they can persist for decades. Some researchers argue that these local traditions help females identify males that are well adapted to particular conditions, though this interpretation remains debated.</p><p>The functions of song are best understood as a form of long-distance advertisement directed at two very different audiences. To rival males, a persistent, vigorous song announces that a territory is occupied and will be defended, often making physical combat unnecessary. Playback studies, in which recorded song is broadcast from a loudspeaker within an unoccupied territory, confirm this: intruding males are noticeably reluctant to settle where song suggests a resident is already present. To females, meanwhile, song serves as an honest signal of a potential partner''s quality. A male capable of maintaining a large and varied repertoire, or of singing at length, may be demonstrating that he is healthy, well fed and free of parasites, since such performances are demanding to sustain.</p><p>The timing of the dawn chorus itself has attracted particular scrutiny. Several explanations have been proposed, and they are not mutually exclusive. The still, cool air of early morning carries sound farther and with less distortion than the turbulent air of midday, so a singer can reach a wider audience for the same effort. Light levels at dawn are often too low for efficient foraging, making the hour a relatively cheap one to devote to singing. There is also evidence that a male who sings energetically at first light signals to listeners that he has survived the perilous night in good condition. Whatever the precise balance of causes, the chorus fades as the morning wears on and the ordinary business of feeding resumes.</p><p>Modern research increasingly relies on automated recording units left in the field for weeks at a time, generating vast archives of sound that software can scan for individual species. Such tools have revealed that birdsong is being reshaped by human activity. In noisy urban environments, some birds now sing at a higher pitch, lifting their notes above the low rumble of traffic so that their messages are not drowned out. Whether such adjustments will prove sufficient as cities continue to expand is a question that ornithologists are only beginning to address.</p>') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,1,5,'tfng','Do the following statements agree with the information in the passage? Write TRUE, FALSE or NOT GIVEN.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,1,'In most bird species, song is produced mainly by males during the breeding season.','"TRUE"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,2,'Birds raised without hearing adult song developed songs identical to those of normally reared birds.','"FALSE"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,3,'The dialect of the white-crowned sparrow is more complex than that of any other songbird.','"NOT GIVEN"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,4,'Playback experiments show that male birds tend to avoid settling in areas where song indicates a territory is already occupied.','"TRUE"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer) VALUES (v_grp,5,'The various explanations offered for the timing of the dawn chorus are regarded as incompatible with one another.','"FALSE"'::jsonb);
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,2,6,9,'sentence_completion','Complete each sentence with NO MORE THAN TWO WORDS from the passage.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,6,'The vocal organ that allows birds to produce their wide acoustic range is called the ______.','"syrinx"'::jsonb,'["syrinx"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,7,'Young songbirds memorise adult songs during an early ______ in their lives.','"sensitive period"'::jsonb,'["sensitive period"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,8,'Regional differences in the song of a single species are known as a ______.','"dialect"'::jsonb,'["dialect"]'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,correct_answer,acceptable_answers) VALUES (v_grp,9,'For females, a male''s song acts as an honest ______ of his quality as a partner.','"signal"'::jsonb,'["signal"]'::jsonb);
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,3,10,13,'mcq_single','Choose the correct letter, A, B, C or D.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,10,'According to the passage, how do calls differ from songs?','[{"letter":"A","text":"Calls are produced only by females."},{"text":"Calls are short sounds that convey immediate information.","letter":"B"},{"letter":"C","text":"Calls are learned during a sensitive period."},{"text":"Calls are used mainly to attract a mate.","letter":"D"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'What point does the passage make about how young birds refine their song?','[{"text":"They imitate the calls of other species.","letter":"A"},{"text":"They rely entirely on genetic instructions.","letter":"B"},{"letter":"C","text":"They must hear themselves as they practise."},{"letter":"D","text":"They stop improving once the breeding season begins."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'Why might a male with a large and varied repertoire be attractive to females?','[{"text":"It allows him to defend a larger territory.","letter":"A"},{"letter":"B","text":"It shows that he can sing at a higher pitch."},{"letter":"C","text":"It proves he belongs to the local dialect group."},{"letter":"D","text":"It suggests he is healthy and free of parasites."}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'What is one reason given for why dawn is a favourable time to sing?','[{"text":"Predators are usually absent at first light.","letter":"A"},{"text":"Cool, still air carries sound farther than midday air.","letter":"B"},{"text":"Females are more active in the early morning.","letter":"C"},{"letter":"D","text":"Singing at dawn requires less learning."}]'::jsonb,'"B"'::jsonb);
